namespace sv_5794d042023c4d30b988bfd6bd2b54a8.Services;

public class WarehouseStateService
{
    private string _currentWarehouseId = "WH-1";

    public string CurrentWarehouseId => _currentWarehouseId;

    public event Action? OnWarehouseChanged;

    public IReadOnlyList<WarehouseInfo> Warehouses { get; } =
    [
        new("WH-1", "Warehouse A — Main Distribution"),
        new("WH-2", "Warehouse B — East Regional"),
        new("WH-3", "Warehouse C — West Regional"),
        new("WH-4", "Warehouse D — Cold Storage"),
    ];

    public void SetWarehouse(string warehouseId)
    {
        if (_currentWarehouseId == warehouseId) return;
        _currentWarehouseId = warehouseId;
        OnWarehouseChanged?.Invoke();
    }
}

public record WarehouseInfo(string Id, string Name);

namespace sv_5794d042023c4d30b988bfd6bd2b54a8.Services;

public class InventoryAlertService : IDisposable
{
    private readonly WarehouseStateService _warehouseState;
    private readonly Random _random = new();
    private PeriodicTimer? _timer;
    private CancellationTokenSource? _cts;
    private int _subscriberCount;

    public int LatestLowStockCount { get; private set; }

    public event Action? OnAlertCountChanged;

    public InventoryAlertService(WarehouseStateService warehouseState)
    {
        _warehouseState = warehouseState;
        _warehouseState.OnWarehouseChanged += HandleWarehouseChanged;
    }

    /// <summary>Simulates a database query for low-stock items.</summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        return Task.FromResult(_random.Next(0, 16));
    }

    /// <summary>
    /// Call when a component that needs polling becomes active.
    /// Polling starts on the first subscriber and stops when the last unsubscribes.
    /// </summary>
    public void StartPolling()
    {
        _subscriberCount++;
        if (_subscriberCount == 1)
        {
            _cts = new CancellationTokenSource();
            _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
            _ = PollLoopAsync(_cts.Token);
        }
    }

    /// <summary>Call when a component that needs polling is disposed.</summary>
    public void StopPolling()
    {
        _subscriberCount = Math.Max(0, _subscriberCount - 1);
        if (_subscriberCount == 0)
        {
            CancelTimer();
        }
    }

    public async Task RefreshNowAsync()
    {
        LatestLowStockCount = await GetLowStockCountAsync(_warehouseState.CurrentWarehouseId);
        OnAlertCountChanged?.Invoke();
    }

    private async Task PollLoopAsync(CancellationToken ct)
    {
        // Fetch immediately on start so UI isn't empty
        await RefreshNowAsync();

        try
        {
            while (_timer is not null && await _timer.WaitForNextTickAsync(ct))
            {
                await RefreshNowAsync();
            }
        }
        catch (OperationCanceledException) { /* expected on stop */ }
    }

    private async void HandleWarehouseChanged()
    {
        if (_subscriberCount > 0)
        {
            await RefreshNowAsync();
        }
    }

    private void CancelTimer()
    {
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = null;
        _timer?.Dispose();
        _timer = null;
    }

    public void Dispose()
    {
        _warehouseState.OnWarehouseChanged -= HandleWarehouseChanged;
        CancelTimer();
    }
}

