@using sv_5794d042023c4d30b988bfd6bd2b54a8.Services
@inject WarehouseStateService WarehouseState
@inject InventoryAlertService AlertService
@implements IDisposable
@rendermode InteractiveServer

<PageTitle>Warehouse Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="row mt-4">
    <div class="col-md-4">
        <div class="card">
            <div class="card-body text-center">
                <h5 class="card-title text-muted">Current Warehouse</h5>
                <p class="display-6">@CurrentWarehouseName</p>
                <p class="text-muted">@WarehouseState.CurrentWarehouseId</p>
            </div>
        </div>
    </div>

    <div class="col-md-4">
        <div class="card @(AlertService.LatestLowStockCount > 0 ? "border-danger" : "border-success")">
            <div class="card-body text-center">
                <h5 class="card-title text-muted">Low Stock Alerts</h5>
                <p class="display-3 @(AlertService.LatestLowStockCount > 0 ? "text-danger" : "text-success")">
                    @AlertService.LatestLowStockCount
                </p>
                <p class="text-muted">Items below minimum level</p>
            </div>
        </div>
    </div>

    <div class="col-md-4">
        <div class="card">
            <div class="card-body text-center">
                <h5 class="card-title text-muted">Polling Status</h5>
                <p class="display-6 text-success">● Active</p>
                <p class="text-muted">Refreshes every 10 seconds</p>
            </div>
        </div>
    </div>
</div>

<div class="row mt-4">
    <div class="col-12">
        <button class="btn btn-outline-primary" @onclick="ManualRefresh">Refresh Now</button>
        <span class="text-muted ms-3">Last update: @_lastUpdate.ToString("HH:mm:ss")</span>
    </div>
</div>

@code {
    private DateTime _lastUpdate = DateTime.Now;

    private string CurrentWarehouseName =>
        WarehouseState.Warehouses
            .FirstOrDefault(w => w.Id == WarehouseState.CurrentWarehouseId)?.Name
        ?? WarehouseState.CurrentWarehouseId;

    protected override void OnInitialized()
    {
        WarehouseState.OnWarehouseChanged += StateHasChangedSafe;
        AlertService.OnAlertCountChanged += OnAlertUpdated;

        // Start polling — this page owns the polling lifecycle
        AlertService.StartPolling();
    }

    private async Task ManualRefresh()
    {
        await AlertService.RefreshNowAsync();
    }

    private void OnAlertUpdated()
    {
        _lastUpdate = DateTime.Now;
        InvokeAsync(StateHasChanged);
    }

    private void StateHasChangedSafe()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        WarehouseState.OnWarehouseChanged -= StateHasChangedSafe;
        AlertService.OnAlertCountChanged -= OnAlertUpdated;

        // Stop polling when leaving the dashboard
        AlertService.StopPolling();
    }
}

