@using sv_5794d042023c4d30b988bfd6bd2b54a8.Services
@inject WarehouseStateService WarehouseState
@implements IDisposable
@rendermode InteractiveServer

<select class="form-select form-select-sm" style="width: 280px;"
        value="@WarehouseState.CurrentWarehouseId"
        @onchange="OnSelectionChanged">
    @foreach (var wh in WarehouseState.Warehouses)
    {
        <option value="@wh.Id">@wh.Name</option>
    }
</select>

@code {
    protected override void OnInitialized()
    {
        WarehouseState.OnWarehouseChanged += StateHasChangedSafe;
    }

    private void OnSelectionChanged(ChangeEventArgs e)
    {
        var id = e.Value?.ToString();
        if (!string.IsNullOrEmpty(id))
        {
            WarehouseState.SetWarehouse(id);
        }
    }

    private void StateHasChangedSafe()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        WarehouseState.OnWarehouseChanged -= StateHasChangedSafe;
    }
}

